import{g as e,o as s,c as o,al as n}from"./chunks/framework.CrxCEdOb.js";const h=JSON.parse('{"title":"06 目录与部署","description":"项目目录结构、侧栏生成规则、推送部署与常见坑。","frontmatter":{"title":"06 目录与部署","description":"项目目录结构、侧栏生成规则、推送部署与常见坑。"},"headers":[],"relativePath":"notes/writing-guide/06-deploy.md","filePath":"notes/writing-guide/06-deploy.md","lastUpdated":1793364501000}'),l={name:"notes/writing-guide/06-deploy.md"};function i(c,a,t,d,p,r){return s(),o("div",null,[...a[0]||(a[0]=[n(`<h1 id="目录与部署" tabindex="-1">目录与部署 <a class="header-anchor" href="#目录与部署" aria-label="Permalink to &quot;目录与部署&quot;">​</a></h1><h2 id="目录结构" tabindex="-1">目录结构 <a class="header-anchor" href="#目录结构" aria-label="Permalink to &quot;目录结构&quot;">​</a></h2><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki css-variables vp-code" tabindex="0"><code><span class="line"><span>docs/</span></span>
<span class="line"><span>├── index.md              # 首页（layout: home）</span></span>
<span class="line"><span>├── ai/                   # 普通文章，侧栏自动生成</span></span>
<span class="line"><span>├── notes/                # 这份手册</span></span>
<span class="line"><span>├── test/                 # 测试稿</span></span>
<span class="line"><span>├── pages/                # 归档 / 标签 / 文章列表 / 案例页</span></span>
<span class="line"><span>├── travel/               # 游记页</span></span>
<span class="line"><span>├── public/               # 静态资源，映射到站点根路径</span></span>
<span class="line"><span>└── .vitepress/           # 配置、主题、组件</span></span></code></pre></div><h2 id="侧栏规则" tabindex="-1">侧栏规则 <a class="header-anchor" href="#侧栏规则" aria-label="Permalink to &quot;侧栏规则&quot;">​</a></h2><ul><li>侧栏由 <code>vitepress-sidebar</code> 按目录自动生成，新增 <code>.md</code> 就会出现在对应分组，分组名就是目录名。</li><li>每个目录里的 <code>index.md</code> 会成为该分组的入口页；同级文件按标题排序，所以教程类页面用 <code>01</code>、<code>02</code> 这样的前缀就能定死顺序。</li><li><code>pages/</code> 和 <code>travel/</code> 使用自定义布局，整目录已从自动侧栏排除。</li><li>普通文章不要写 <code>layout</code>；可用值只有 <code>home</code>、<code>tags</code>、<code>posts</code>、<code>case</code>、<code>travel</code>。</li></ul><div class="rp-callout rp-callout--tip"><div class="rp-callout__title">代码块行号</div><div class="rp-callout__content"><p>代码块默认不显示行号。个别块想要行号，在围栏语言后面加 <code>:line-numbers</code>：</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki css-variables vp-code" tabindex="0"><code><span class="line"><span style="color:var(--shiki-token-string);">\`\`\`powershell:line-numbers</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">pnpm dev</span></span>
<span class="line"><span style="color:var(--shiki-token-string);">\`\`\`</span></span></code></pre></div></div></div><h2 id="部署" tabindex="-1">部署 <a class="header-anchor" href="#部署" aria-label="Permalink to &quot;部署&quot;">​</a></h2><p>推送到 <code>master</code> 后由 GitHub Actions 构建并部署到 GitHub Pages：</p><div class="language-powershell"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki css-variables vp-code" tabindex="0"><code><span class="line"><span style="color:var(--shiki-foreground);">git add .</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">git commit </span><span style="color:var(--shiki-token-keyword);">-</span><span style="color:var(--shiki-foreground);">m </span><span style="color:var(--shiki-token-string-expression);">&quot;更新文章&quot;</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">git push</span></span></code></pre></div><p>GitHub Pages 的缓存策略是 <code>Cache-Control: max-age=600</code>，HTML 和静态资源 10 分钟后重新校验；视频由 <code>sw.js</code> 缓存，规则见 <a href="./05-media">图片与视频</a>。</p><div class="rp-callout rp-callout--caution"><div class="rp-callout__title">部署后先看线上</div><div class="rp-callout__content"><p>本地构建通过不代表线上正常，视频、图片这类大文件尤其要打开线上页面实际点一遍。改了样式或字体时，先硬刷新（Ctrl+F5）再判断，否则看到的可能还是十分钟前的旧产物。</p></div></div><h2 id="容易踩的坑" tabindex="-1">容易踩的坑 <a class="header-anchor" href="#容易踩的坑" aria-label="Permalink to &quot;容易踩的坑&quot;">​</a></h2><ul><li>容器开头的 <code>:::</code> 后不要紧跟中文内容；标题用空格或 <code>{title=&quot;…&quot;}</code>。</li><li>嵌套容器外层必须比内层多冒号，否则内层会被提前闭合。</li><li><code>:::prompt</code> 正文是逐字复制的，里面不要再套容器；需要 markdown 渲染就用 <code>{custom}</code>。</li><li>视频没压缩、<code>moov</code> 在文件尾时，浏览器要两次请求才能起播，表现为「点了半天没反应」。</li><li>图片和视频路径不要写 <code>public</code>：<code>/public/video/a.mp4</code> 会 404，正确写法是 <code>/video/a.mp4</code>。</li><li>文章没有 <code>date</code> 就不会进归档列表；有 <code>date</code> 但没有 <code>description</code>，卡片上会空一块。</li></ul>`,13)])])}const v=e(l,[["render",i]]);export{h as __pageData,v as default};
